-- Adhunik ERP - Phase 7A Enterprise Item Master
begin;
create table public.item_categories(id uuid primary key default gen_random_uuid(),code text,name text not null check(length(trim(name))>0),description text,sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id)default auth.uid(),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id)default auth.uid());
create table public.item_types(like public.item_categories including defaults including constraints);alter table public.item_types add primary key(id);
create table public.item_brands(like public.item_categories including defaults including constraints);alter table public.item_brands add primary key(id);
create table public.units_of_measurement(like public.item_categories including defaults including constraints);alter table public.units_of_measurement add primary key(id);
do $$declare t text;begin foreach t in array array['item_types','item_brands','units_of_measurement']loop execute format('alter table public.%I add constraint %I_created_by_fkey foreign key(created_by) references auth.users(id)',t,t);execute format('alter table public.%I add constraint %I_updated_by_fkey foreign key(updated_by) references auth.users(id)',t,t);end loop;end;$$;
create table public.item_subcategories(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.item_categories(id)on delete restrict,code text,name text not null check(length(trim(name))>0),description text,sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id)default auth.uid(),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id)default auth.uid());
create unique index item_categories_name_unique on public.item_categories(lower(trim(name)));create unique index item_categories_code_unique on public.item_categories(upper(trim(code)))where code is not null;
create unique index item_types_name_unique on public.item_types(lower(trim(name)));create unique index item_types_code_unique on public.item_types(upper(trim(code)))where code is not null;
create unique index item_brands_name_unique on public.item_brands(lower(trim(name)));create unique index item_brands_code_unique on public.item_brands(upper(trim(code)))where code is not null;
create unique index units_of_measurement_name_unique on public.units_of_measurement(lower(trim(name)));create unique index units_of_measurement_code_unique on public.units_of_measurement(upper(trim(code)))where code is not null;
create unique index item_subcategories_name_unique on public.item_subcategories(category_id,lower(trim(name)));create unique index item_subcategories_code_unique on public.item_subcategories(category_id,upper(trim(code)))where code is not null;create index item_subcategories_category_display on public.item_subcategories(category_id,is_active,sort_order,name);
create table public.items(id uuid primary key default gen_random_uuid(),item_code text not null check(length(trim(item_code))>0),item_name text not null check(length(trim(item_name))>0),image_path text,category_id uuid not null references public.item_categories(id)on delete restrict,subcategory_id uuid references public.item_subcategories(id)on delete restrict,item_type_id uuid references public.item_types(id)on delete restrict,brand_id uuid references public.item_brands(id)on delete restrict,model_part_number text,description text,hsn_code text,unit_id uuid not null references public.units_of_measurement(id)on delete restrict,length_mm numeric(18,3)check(length_mm is null or length_mm>=0),breadth_mm numeric(18,3)check(breadth_mm is null or breadth_mm>=0),height_mm numeric(18,3)check(height_mm is null or height_mm>=0),unit_volume_mm3 numeric(30,3)generated always as(coalesce(length_mm,0)*coalesce(breadth_mm,0)*coalesce(height_mm,0))stored,unit_weight_kg numeric(18,6)check(unit_weight_kg is null or unit_weight_kg>=0),minimum_stock_level numeric(18,4)check(minimum_stock_level is null or minimum_stock_level>=0),reorder_level numeric(18,4)check(reorder_level is null or reorder_level>=0),is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id)default auth.uid(),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id)default auth.uid(),deactivated_at timestamptz,deactivated_by uuid references auth.users(id),constraint items_deactivation_state check((is_active and deactivated_at is null and deactivated_by is null)or(not is_active and deactivated_at is not null and deactivated_by is not null)));
create unique index items_code_unique on public.items(lower(trim(item_code)));create index items_search on public.items(lower(item_name),lower(coalesce(model_part_number,'')),lower(coalesce(hsn_code,'')));create index items_classification on public.items(category_id,subcategory_id,item_type_id,brand_id,unit_id,is_active);
create table public.item_activities(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.items(id)on delete restrict,activity_type text not null check(activity_type in('CREATED','EDITED','IMAGE_UPDATED','DEACTIVATED','REACTIVATED')),description text not null,created_by uuid not null references auth.users(id)default auth.uid(),created_at timestamptz not null default now());create index item_activities_parent on public.item_activities(item_id,created_at desc);
alter table public.proforma_invoice_items add constraint proforma_invoice_items_inventory_item_id_fkey foreign key(inventory_item_id)references public.items(id)on delete restrict;create index proforma_invoice_items_inventory_item on public.proforma_invoice_items(inventory_item_id)where inventory_item_id is not null;
alter table public.packing_list_items add column item_id uuid references public.items(id)on delete restrict,add column unit_weight_kg numeric(18,6)check(unit_weight_kg is null or unit_weight_kg>=0);create index packing_list_items_item on public.packing_list_items(item_id)where item_id is not null;
create function public.validate_item_classification()returns trigger language plpgsql set search_path=''as $$begin new.item_code:=trim(new.item_code);new.item_name:=trim(new.item_name);if new.subcategory_id is not null and not exists(select 1 from public.item_subcategories s where s.id=new.subcategory_id and s.category_id=new.category_id)then raise exception 'Subcategory does not belong to selected category';end if;if tg_op='UPDATE'and new.item_code<>old.item_code and exists(select 1 from public.proforma_invoice_items p where p.inventory_item_id=old.id)then raise exception 'Item Code cannot change after use';end if;return new;end;$$;create trigger validate_item_classification before insert or update on public.items for each row execute function public.validate_item_classification();
create function public.log_item_change()returns trigger language plpgsql security definer set search_path=''as $$begin insert into public.item_activities(item_id,activity_type,description,created_by)values(new.id,case when tg_op='INSERT'then'CREATED'when old.is_active and not new.is_active then'DEACTIVATED'when not old.is_active and new.is_active then'REACTIVATED'when old.image_path is distinct from new.image_path then'IMAGE_UPDATED'else'EDITED'end,case when tg_op='INSERT'then'Item created'when old.is_active and not new.is_active then'Item deactivated'when not old.is_active and new.is_active then'Item reactivated'when old.image_path is distinct from new.image_path then'Item image updated'else'Item master updated'end,coalesce(new.updated_by,new.created_by,auth.uid()));return new;end;$$;create trigger log_item_change after insert or update on public.items for each row execute function public.log_item_change();
create function public.default_packing_item_from_master()returns trigger language plpgsql set search_path=''as $$declare m public.items%rowtype;begin select i.* into m from public.proforma_invoice_items p join public.items i on i.id=p.inventory_item_id where p.id=new.pi_item_id;if found then new.item_id:=m.id;new.item_length_mm:=m.length_mm;new.item_breadth_mm:=m.breadth_mm;new.item_height_mm:=m.height_mm;new.unit_weight_kg:=m.unit_weight_kg;end if;return new;end;$$;create trigger default_packing_item_from_master before insert on public.packing_list_items for each row execute function public.default_packing_item_from_master();
do $$declare t text;begin foreach t in array array['item_categories','item_subcategories','item_types','item_brands','units_of_measurement']loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()','set_'||t||'_updated_at',t);execute format('alter table public.%I enable row level security',t);execute format('create policy "ERP read %I" on public.%I for select to authenticated using(public.has_active_erp_access())',t,t);execute format('create policy "Admin insert %I" on public.%I for insert to authenticated with check(public.is_erp_admin())',t,t);execute format('create policy "Admin update %I" on public.%I for update to authenticated using(public.is_erp_admin())with check(public.is_erp_admin())',t,t);end loop;end;$$;
create trigger set_items_updated_at before update on public.items for each row execute function public.set_updated_at();alter table public.items enable row level security;alter table public.item_activities enable row level security;
create policy "ERP read items"on public.items for select to authenticated using(public.has_active_erp_access());create policy "Managers insert items"on public.items for insert to authenticated with check(public.current_erp_role()in('ADMIN','MANAGER')and created_by=auth.uid());create policy "Managers update items"on public.items for update to authenticated using(public.current_erp_role()in('ADMIN','MANAGER'))with check(public.current_erp_role()in('ADMIN','MANAGER'));create policy "ERP read item activity"on public.item_activities for select to authenticated using(public.has_active_erp_access());
grant select,insert,update on public.item_categories,public.item_subcategories,public.item_types,public.item_brands,public.units_of_measurement,public.items to authenticated;grant select on public.item_activities to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('item-images','item-images',false,5242880,array['image/jpeg','image/png','image/webp'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "ERP read item images"on storage.objects for select to authenticated using(bucket_id='item-images'and public.has_active_erp_access());create policy "Managers insert item images"on storage.objects for insert to authenticated with check(bucket_id='item-images'and public.current_erp_role()in('ADMIN','MANAGER'));create policy "Managers update item images"on storage.objects for update to authenticated using(bucket_id='item-images'and public.current_erp_role()in('ADMIN','MANAGER'))with check(bucket_id='item-images'and public.current_erp_role()in('ADMIN','MANAGER'));create policy "Managers delete item images"on storage.objects for delete to authenticated using(bucket_id='item-images'and public.current_erp_role()in('ADMIN','MANAGER'));
comment on table public.items is 'Catalogue master only; inventory balances belong to Phase 7B.';comment on column public.proforma_invoice_items.inventory_item_id is 'Optional master reference; PI fields are snapshots.';comment on column public.packing_list_items.item_id is 'Optional master lineage; packing dimensions are snapshots.';
commit;
